-- Supabase needs these blank, not empty, for password sign-in to work
do $$ declare c text; begin
  for c in select column_name from information_schema.columns where table_schema = 'auth' and table_name = 'users'
    and column_name in ('confirmation_token', 'recovery_token', 'email_change_token_new', 'email_change', 'email_change_token_current', 'phone_change', 'phone_change_token', 'reauthentication_token') loop
    execute format('update auth.users set %I = coalesce(%I, '''') where email like ''%%@graceville.example''', c, c);
  end loop;
end $$;

-- Events go in as the lead pastor, who is allowed to publish them
select set_config('request.jwt.claim.sub', '4df7bfc0-b817-4d77-a9ee-f4d794bdce9c', true);
insert into events (id, church_id, slug, status, created_by, data) select id, church_id, slug, status, created_by, data from jsonb_populate_recordset(null::events, pg_temp.shift($demo$[
{"id":"ev-youth","church_id":"19751155-65fe-4b57-bf0f-5d548bcabeba","slug":"rise-2026","status":"published","created_by":"3da60f26-76d2-479f-9a45-55f75f0c8805","data":{"id":"ev-youth","slug":"rise-2026","title":"Rise: Youth Conference 2026","tagline":"Three days of worship, the Word and fire for a new generation.","cover":0,"theme":"Arise and Shine","verse":{"text":"Arise, shine; for your light has come! And the glory of the Lord is risen upon you.","ref":"Isaiah 60:1"},"template":"bold","description":"Rise is our yearly gathering for young people: powerful worship, practical teaching on purpose, career and relationships, and time to pray together. Bring a friend!","start":"2026-12-18T09:00:00.000Z","end":"2026-12-20T15:00:00.000Z","days":["2026-12-18","2026-12-19","2026-12-20"],"mode":"hybrid","venue":"Graceville Church main auditorium, Lagos","link":"https://youtube.com/@gracevillechurch/live","dayPlan":[{"date":"2026-12-18","start":"17:00","end":"21:00","title":"Opening night","sessions":[{"id":"s1","start":"17:00","end":"18:00","title":"Praise and worship","personIds":["pp3"]},{"id":"s2","start":"18:00","end":"19:30","title":"Opening message: Arise","personIds":["pp1"]},{"id":"s3","start":"19:30","end":"21:00","title":"Night of prayer","personIds":["pp1","pp3"]}]},{"date":"2026-12-19","start":"10:00","end":"16:00","title":"Purpose and career","sessions":[{"id":"s4","start":"10:00","end":"11:00","title":"Worship"},{"id":"s5","start":"11:00","end":"12:30","title":"Finding your purpose","personIds":["pp2"]},{"id":"s6","start":"13:30","end":"15:00","title":"Workshops: career, tech, business","venueId":"v2"},{"id":"s7","start":"15:00","end":"16:00","title":"Panel: faith at work","personIds":["pp2","pp4"]}]},{"date":"2026-12-20","start":"10:00","end":"14:00","title":"Shine","sessions":[{"id":"s8","start":"10:00","end":"11:30","title":"Worship and the Word","personIds":["pp1","pp3"]},{"id":"s9","start":"11:30","end":"14:00","title":"Commissioning and celebration"}]}],"people":[{"id":"pp1","name":"Pastor Joshua Eze","label":"Speaker","bio":"Associate pastor at Graceville Church and convener of Rise. Passionate about raising young people who carry God's presence into every field.","from":"Graceville Church"},{"id":"pp2","name":"Victor Ogunleye","label":"Speaker","bio":"Head of the Faculty of Training, coach and author on purpose and careers.","from":"Kingdom Careers"},{"id":"pp3","name":"Graceville Voices","label":"Music minister","bio":"The Graceville Church choir, leading worship across all three days."},{"id":"pp4","name":"Tolu Adeyemi","label":"Special guest","bio":"Founder of a Lagos fintech start-up, on building with integrity.","from":"Lagos"},{"id":"pp5","name":"Seyi Lawal","label":"Host"}],"venues":[{"id":"v1","name":"Main auditorium","address":"14 Church Street, Ogba, Ikeja, Lagos","directions":"Enter through Gate B on Church Street. Parking in the school field opposite.","mapUrl":"https://maps.google.com/?q=Ogba+Ikeja+Lagos"},{"id":"v2","name":"Youth hall (workshops)","address":"Same compound, behind the main auditorium","overflow":false},{"id":"v3","name":"Overflow: church car park tent","note":"With a big screen when the auditorium is full","overflow":true}],"regTypes":["individual","group","online"],"faq":[{"q":"Is Rise free?","a":"Yes. Registration is free, and lunch is provided on Saturday."},{"q":"Who can come?","a":"Rise is for young people from 13 to 35, from any church. Parents are welcome on the opening night."},{"q":"Can I register my friends?","a":"Yes. Choose Group when you register and add each friend. Everyone gets their own ticket."},{"q":"Will it be streamed?","a":"Yes, on our YouTube channel. Register as Online to get the link and reminders."}],"stay":[{"name":"Ikeja guest houses near the church","note":"Ask guest services for a list of nearby options"}],"give":{"label":"Support Rise","bank":"Zenith Bank","account":"1012345678","accountName":"Graceville Church Youth"},"contact":{"name":"Rise guest servi